import{_ as o,c as t,o as r,b2 as c}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"C7DatePicker 日期选择器","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-date-picker.md","filePath":"docs/frontend/components/通用组件/c7-date-picker.md"}'),n={name:"docs/frontend/components/通用组件/c7-date-picker.md"};function d(s,e,a,g,i,l){return r(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="c7datepicker-日期选择器" tabindex="-1">C7DatePicker 日期选择器 <a class="header-anchor vp-link" href="#c7datepicker-日期选择器" aria-label="Permalink to &quot;C7DatePicker 日期选择器&quot;">​</a></h1><p>在 <strong><code>ElDatePicker</code></strong> 上统一 <strong><code>type</code> → 默认 <code>format</code> / <code>valueFormat</code></strong>（未传时）、范围 <strong><code>rangeMerge</code></strong>（合并为单字符串或保持 EP 数组）与 <strong><code>mergeDelimiter</code></strong>（存储分隔符，与 EP <strong><code>rangeSeparator</code></strong> 分离）。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7DatePicker/index.vue</code><br><strong>Dev 页</strong>：开发服务器启动后访问 <code>/dev/c7-datepicker-e2e</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong>默认格式</strong>：命中内置表（含 <strong><code>week</code></strong> → <strong><code>gggg-wo</code></strong>）时注入；父传入 <strong><code>format</code> / <code>value-format</code></strong> 则 <strong>覆盖</strong>；未命中 <strong><code>type</code></strong> <strong>不注入</strong>。</li><li><strong>范围 <code>type</code></strong>：<strong><code>daterange</code> / <code>datetimerange</code> / <code>monthrange</code> / <code>yearrange</code></strong>。</li><li><strong><code>rangeMerge</code></strong>（默认 <strong><code>false</code></strong>）：<strong><code>true</code></strong> 时 <strong><code>v-model</code></strong> 为 <strong><code>mergeDelimiter</code></strong> 拼接的 <strong>单字符串</strong>；<strong><code>false</code></strong> 时为 <strong>EP 范围数组</strong>。</li><li><strong>回显</strong>：父级传 <strong><code>&quot;开始,结束&quot;</code></strong>（或自定义 <strong><code>mergeDelimiter</code></strong>）时拆成数组供面板编辑；非法串 <strong><code>console.warn</code></strong> 并清空为 <strong><code>null</code></strong>。</li><li><strong>事件</strong>：<strong><code>update:modelValue</code></strong>、<strong><code>change</code></strong>（载荷与对外 <strong><code>v-model</code></strong> 形态一致）、<strong><code>blur</code></strong>、<strong><code>focus</code></strong>。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p>在 <code>main.js</code> 已调用 <code>installPackages(app)</code> 时，模板中可直接使用 <code>&lt;c7-date-picker /&gt;</code>（或 <code>&lt;C7DatePicker /&gt;</code>）。</p><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><ul><li>设计说明：<code>docs/superpowers/specs/2026-05-07-c7-datepicker-design.md</code></li><li>OpenSpec：<code>openspec/changes/ui-c7-datepicker/specs/ui-c7-datepicker/spec.md</code></li></ul>',9)])])}const u=o(n,[["render",d]]);export{m as __pageData,u as default};
